const tenders =  [
  {
    id: "tender-001",
    title: "Global HRIS Integration Across 11 Countries",
    issuer: "Meridian Consumer Goods Group",
    deadline: "2026-11-20",
    raw_text: "Meridian Consumer Goods Group is consolidating HR data for 4,200 employees across 11 countries. We operate SAP SuccessFactors for core HR, a third-party talent marketplace for contingent staffing, and four separate local payroll systems. We require an integration layer built on MuleSoft to unify these into a single employee record, with master data management so duplicate employees are not created across systems. Payroll interfaces must respect local statutory reporting formats. The integration must be deployed as versioned APIs and documented for our internal IT team, who will maintain it after handover.",
    source: "simulated_feed",
    requirements: [
      "MuleSoft integration layer unifying SuccessFactors, talent marketplace, and 4 local payroll systems",
      "Master data management with cross-system duplicate employee prevention",
      "Statutory payroll reporting formats per country",
      "Versioned API layer with handover documentation to internal IT"
    ]
  },

];

return tenders.map(tender => ({
  json: {
    ...tender
  },
}));

const tender = $('1 - Ingest and Normalize Tender').first().json;
const research = $json;
const requirements = Array.isArray(tender.requirements) ? tender.requirements : [];

const queryParts = [
  tender.title,
  tender.sector,
  ...requirements,
  research.sector,
  ...(research.domain_requirements ?? []),
  ...(research.past_projects ?? []),
  ...(research.key_partners ?? []),
].filter(Boolean);

return [{
  json: {
    tender,
    research,
    rag_query: queryParts.join('. ').slice(0, 10000),
    config: $('Validate Tender and Configure URLs').first().json.config,
  },
}];

const values = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const matches = values.filter((value) => value && value.id);
return [{ json: { cv_matches: matches } }];

const values = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const matches = values.filter((value) => value && value.id);
return [{ json: { project_matches: matches } }];

const context = $('Prepare RAG Context').first().json;
const tender = context.tender;
const research = context.research;
const cvMatches = Array.isArray($json.cv_matches) ? $json.cv_matches : [];
const projectMatches = Array.isArray($json.project_matches) ? $json.project_matches : [];
const toolMatches = Array.isArray($json.tool_matches) ? $json.tool_matches : [];
const allMatches = [...cvMatches, ...projectMatches, ...toolMatches];

const tokens = (text) => new Set(String(text ?? '').toLowerCase().match(/[a-z0-9+#.]{3,}/g) ?? []);
const coverageFor = (requirement, match) => {
  const required = tokens(requirement);
  const evidence = tokens(`${match.content ?? ''} ${JSON.stringify(match.metadata ?? {})}`);
  const overlap = required.size ? [...required].filter((token) => evidence.has(token)).length / required.size : 0;
  const semantic = Math.max(0, Math.min(1, Number(match.similarity ?? 0)));
  return Math.round((semantic * 0.65 + overlap * 0.35) * 100);
};

const requirementsMatrix = (tender.requirements ?? []).map((requirement) => {
  const ranked = allMatches
    .map((match) => ({ match, score: coverageFor(requirement, match) }))
    .sort((a, b) => b.score - a.score);
  const best = ranked[0];
  const score = best?.score ?? 0;
  return {
    requirement,
    coverage_score: score,
    status: score >= 70 ? 'strong' : score >= 45 ? 'partial' : 'gap',
    best_asset: best ? {
      record_id: best.match.metadata?.record_id ?? best.match.id,
      doc_type: best.match.doc_type,
      similarity: best.match.similarity,
      evidence: best.match.content,
    } : null,
  };
});

const overallCoverage = requirementsMatrix.length
  ? Math.round(requirementsMatrix.reduce((sum, row) => sum + row.coverage_score, 0) / requirementsMatrix.length)
  : 0;
const gaps = requirementsMatrix.filter((row) => row.status === 'gap');
const daysToDeadline = Math.ceil((Date.parse(`${tender.deadline}T00:00:00Z`) - Date.now()) / 86400000);
const risks = [];
if (research.confidence === 'low') risks.push('Prospect research confidence is low and needs human verification.');
if (!cvMatches.length) risks.push('No matching CV was retrieved.');
if (!projectMatches.length) risks.push('No matching project reference was retrieved.');
if (!toolMatches.length) risks.push('No matching OliveSoft capability was retrieved.');
if (!research.estimated_budget) risks.push('No sourced procurement budget was found; validate the commercial range with the client.');
if (!(research.competitor_insights ?? []).length) risks.push('No sourced incumbent or competitor signal was found.');
if (gaps.length) risks.push(`${gaps.length} tender requirement(s) have weak internal coverage.`);
if (daysToDeadline < 14) risks.push(`Deadline is close (${daysToDeadline} day(s) remaining).`);

const recommendedTeam = cvMatches.map((match) => ({
  cv_id: match.metadata?.record_id ?? match.id,
  person: match.metadata?.person ?? null,
  role: match.metadata?.role ?? null,
  skills: match.metadata?.skills ?? [],
  similarity: match.similarity,
  evidence: match.content,
}));
const relevantProjects = projectMatches.map((match) => ({
  project_id: match.metadata?.record_id ?? match.id,
  sector: match.metadata?.client_sector ?? null,
  tech_stack: match.metadata?.tech_stack ?? [],
  similarity: match.similarity,
  evidence: match.content,
}));

return [{
  json: {
    status: 'completed',
    orchestration_version: '1.2.0',
    generated_at: new Date().toISOString(),
    tender,
    prospect_research: research,
    rag_matches: { cvs: cvMatches, projects: projectMatches, capabilities: toolMatches },
    requirements_matrix: requirementsMatrix,
    overall_coverage_score: overallCoverage,
    proposal_brief: {
      title: `Commercial Proposal - ${tender.title}`,
      client: tender.issuer,
      executive_summary: `OliveSoft proposes a tailored delivery approach for ${tender.issuer}'s ${tender.title}.`,
      opportunity_context: {
        sector: research.sector ?? tender.sector,
        estimated_revenue: research.estimated_revenue ?? null,
        estimated_budget: research.estimated_budget ?? null,
        competitor_insights: research.competitor_insights ?? [],
        key_partners: research.key_partners ?? [],
        domain_requirements: research.domain_requirements ?? [],
        matched_capabilities: toolMatches.map((match) => ({
          tool_id: match.metadata?.record_id ?? match.id,
          name: match.metadata?.name ?? null,
          category: match.metadata?.category ?? null,
          similarity: match.similarity,
          evidence: match.content,
        })),
        sources: research.sources ?? [],
        research_confidence: research.confidence,
      },
      recommended_team: recommendedTeam,
      relevant_case_studies: relevantProjects,
      technical_approach: (tender.requirements ?? []).map((requirement, index) => ({
        phase: index + 1,
        objective: requirement,
        coverage: requirementsMatrix[index]?.status ?? 'gap',
      })),
      risks,
      next_actions: [
        'Sales manager validates research sources and assumptions.',
        'Commercial owner validates the sourced budget and competitive signals.',
        'Technical lead confirms the proposed team and availability.',
        'Proposal owner resolves coverage gaps and commercial parameters.',
        'Generate the branded PPTX/PDF after human approval.',
      ],
    },
  },
}];

const values = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const matches = values.filter((value) => value && value.id);
return [{ json: { tool_matches: matches } }];

